// Native execution of supplied ROM bytes; no vendor firmware is bundled.
export function installROM(r){
 r.romInfo=()=>({mode:r.systemROM?'native-dump':'functional-service',base:r.systemROM?.base??null,bytes:r.systemROM?.bytes.length??0,sha256:r.systemROM?.sha256??null});
 r.applyROM=()=>{if(!r.systemROM)return;const {bytes,base}=r.systemROM,e=r.exports,p=e.allocate(bytes.length);try{new Uint8Array(e.memory.buffer,p,bytes.length).set(bytes);if(!e.rom_load(r.cpu,p,bytes.length,base))throw Error('ROM native haritası kurulamadı.');}finally{e.deallocate(p,bytes.length);}};
 r.setSystemROM=async bytes=>{if(bytes===null){r.systemROM=null;r.exports.rom_load(r.cpu,0,0,0);r.system.requestReset(3);return r.romInfo();}const f4=r.board.cpu==='cortex-m4f',base=f4?0x1fff0000:0x1ffff000,max=f4?30720:2048;if(!(bytes instanceof Uint8Array)||bytes.length!==max)throw Error('Bu çip için ROM dökümü '+max+' bayt olmalı.');const data=bytes.slice(),v=new DataView(data.buffer),sp=v.getUint32(0,true),pc=v.getUint32(4,true);if(sp<0x20000000||sp>0x20000000+r.board.ram||sp%4||!(pc&1)||pc<base||pc>=base+max)throw Error('ROM SP/reset vektörü bu çiple uyumsuz.');const digest=await crypto.subtle.digest('SHA-256',data);r.systemROM={base,bytes:data,sha256:Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('')};r.applyROM();if(r.system.bootMode==='system')r.system.requestReset(3);return r.romInfo();};
}
